function getBackgroundMarks(lang) {
    return BACKGROUND_MARKS[lang];
}
function getSpeakers(lang) {
    return SPEAKERS[lang].map(([role, name])=>({
            role,
            name,
            profile: PROFILES[name] ?? null
        }));
}
function getSubthemes() {
    return SUBTHEMES.map((text, i)=>({
            n: ordinal(i + 1),
            text
        }));
}
function getJournals() {
    return JOURNALS.map((text, i)=>({
            n: `${i + 1}.`,
            text
        }));
}
function getCfpDates(lang) {
    return CFP_DATES[lang].map(([label, date])=>({
            label,
            date
        }));
}
function getKeyDates(lang) {
    return [
        ...getCfpDates(lang),
        {
            label: lang === "id" ? "Konferensi ICONZ ke-10" : "The 10th ICONZ",
            date: CONFERENCE.dateRange
        }
    ];
}
